/* Normal production-ABI CLI adapter for a core without a stock Linux CLI.
 * The requests file is generated by this benchmark; no measurement or traffic
 * code executes in the core process. The one returned decimal instance ID is
 * substituted into the generated requests, then normal SIGINT stops the core. */
#define _POSIX_C_SOURCE 200809L
#include "vcore.h"
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>

static char instance[21];

static int invoke(const char *request, int create) {
    char *reply = VCoreInvoke(request);
    if (!reply) return 0;
    int success = strstr(reply, "\"success\":true") != NULL;
    if (success && create) {
        const char *start = strstr(reply, "\"instanceId\":\"");
        if (!start) success = 0;
        else {
            start += strlen("\"instanceId\":\"");
            size_t length = strspn(start, "0123456789");
            if (!length || length > 20 || start[length] != '"' || start[0] == '0') success = 0;
            else { memcpy(instance, start, length); instance[length] = 0; }
        }
    }
    if (!success) fprintf(stderr, "VCore startup/lifecycle request failed: %s\n", reply);
    VCoreFree(reply);
    return success;
}

static int lifecycle(const char *method) {
    char request[160];
    snprintf(request, sizeof(request),
        "{\"apiVersion\":5,\"method\":\"%s\",\"instanceId\":\"%s\",\"payload\":{}}", method, instance);
    return invoke(request, 0);
}

static char *substitute(const char *request) {
    const char *marker = strstr(request, "@INSTANCE@");
    if (!marker) return strdup(request);
    if (!instance[0] || strstr(marker + 10, "@INSTANCE@")) return NULL;
    size_t before = (size_t)(marker - request), length = strlen(instance);
    char *output = malloc(strlen(request) - 10 + length + 1);
    if (!output) return NULL;
    memcpy(output, request, before);
    memcpy(output + before, instance, length);
    strcpy(output + before + length, marker + 10);
    return output;
}

static int observe_geodata(FILE *output) {
    char *reply = VCoreInvoke("{\"apiVersion\":5,\"method\":\"getGeoDataState\",\"payload\":{}}");
    if (!reply) return 0;
    struct timespec now;
    int success = clock_gettime(CLOCK_REALTIME, &now) == 0
        && strstr(reply, "\"success\":true") != NULL;
    if (success) {
        success = fprintf(output, "{\"time_ns\":%lld,\"response\":%s}\n",
            (long long)now.tv_sec * 1000000000LL + now.tv_nsec, reply) > 0
            && fflush(output) == 0;
    }
    VCoreFree(reply);
    return success;
}

int main(int argc, char **argv) {
    if (argc != 2 && argc != 3) { fprintf(stderr, "usage: vcore requests.jsonl [geodata-state.jsonl]\n"); return 2; }
    sigset_t stopped;
    sigemptyset(&stopped); sigaddset(&stopped, SIGINT); sigaddset(&stopped, SIGTERM);
    if (sigprocmask(SIG_BLOCK, &stopped, NULL)) return 2;
    signal(SIGPIPE, SIG_IGN);
    FILE *source = fopen(argv[1], "r");
    if (!source) { perror("requests"); return 2; }
    char *line = NULL;
    size_t capacity = 0;
    int good = 1, count = 0;
    while (getline(&line, &capacity, source) >= 0) {
        if (++count > 4 || strlen(line) > 1024 * 1024) { good = 0; break; }
        char *request = substitute(line);
        if (!request || !invoke(request, count == 2)) good = 0;
        free(request);
        if (!good) break;
    }
    if (ferror(source) || count != 4) good = 0;
    free(line); fclose(source);
    if (good) {
        puts("benchmark-ready"); fflush(stdout);
        if (argc == 3) {
            FILE *observations = fopen(argv[2], "w");
            if (!observations) good = 0;
            else {
                while (good) {
                    if (!observe_geodata(observations)) { good = 0; break; }
                    struct timespec interval = { .tv_sec = 0, .tv_nsec = 100000000 };
                    int received = sigtimedwait(&stopped, NULL, &interval);
                    if (received >= 0) break;
                    if (errno != EAGAIN && errno != EINTR) good = 0;
                }
                if (fclose(observations)) good = 0;
            }
        } else {
            int received;
            if (sigwait(&stopped, &received)) good = 0;
        }
    }
    if (instance[0]) {
        if (!lifecycle("stop")) good = 0;
        if (!lifecycle("destroyInstance")) good = 0;
    }
    return good ? 0 : 1;
}
